          action: "broadcast",
          audience: alert.target,
          title: alert.target === "PP" ? "Pageant Perfect" : alert.target === "VG" ? "Velvet Glow" : "Paige Henderson",
          body: text.slice(0, 120),
          url: clientSite(settings),
          key: alert.id,                 /* so a retry never sends twice */
